import sys
from collections import defaultdict

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def main():
    t = int(sys.stdin.readline().strip())
    for _ in range(t):
        n = int(sys.stdin.readline().strip())
        b = read_ints()
        p = read_ints()

        # Find the root of the tree
        root = -1
        for i in range(n):
            if b[i] == i + 1:
                root = i + 1
                break

        # If no root is found, it's an invalid tree
        if root == -1:
            print(-1)
            continue

        # Calculate distances from the root
        dist = [0] * (n + 1)
        for i in range(1, n + 1):
            j = i
            d = 0
            while b[j - 1] != i:
                j = b[j - 1]
                d += 1
            dist[i] = d

        # Check if the permutation is valid
        if any(dist[p[i]] >= dist[p[i + 1]] for i in range(n - 1)):
            print(-1)
            continue

        # Assign weights to edges
        weights = [0] * (n + 1)
        for i in range(1, n + 1):
            if i != root:
                weights[i] = dist[p[dist[i]]] - dist[i]

        # Print the weights
        print(' '.join(map(str, weights[1:])) if all(weights[i] > 0 for i in range(1, n + 1)) else -1)

if __name__ == "__main__":
    main()
